// ─── File: SecurityDemo.java ───
// Runnable demo: gateway auth, RBAC, and zero-trust per-service authorization.
package com.bank.security;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class SecurityDemo {

    private static final Logger log = Logger.getLogger("Security");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        log.setUseParentHandlers(false);
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        AuthGateway gateway = new AuthGateway("nbin-signing-key-from-vault");
        RbacAuthorizer authorizer = new RbacAuthorizer();
        AccountService accounts = new AccountService(authorizer);
        TransferService transfers = new TransferService(authorizer);

        // 1) Customer Rajesh logs in → gateway authenticates and issues a signed JWT.
        Jwt rajeshToken = gateway.login("rajesh", "correct-password", Set.of("CUSTOMER"));
        log.info(() -> "Rajesh authenticated, roles=" + rajeshToken.roles);
        transfers.transfer(rajeshToken, "SAV2001", "CUR3001", new BigDecimal("50000"));

        // 2) Support agent can VIEW but is DENIED transfer (RBAC).
        Jwt agentToken = gateway.login("agent01", "agent-pass", Set.of("SUPPORT"));
        accounts.viewAccount(agentToken, "SAV2001");            // allowed
        try { transfers.transfer(agentToken, "SAV2001", "CUR3001", new BigDecimal("1000")); }
        catch (SecurityException e) { log.severe("Agent transfer DENIED: " + e.getMessage()); }

        // 3) Forged / missing token → rejected by zero-trust validation.
        Jwt forged = new Jwt("attacker", Set.of("CUSTOMER"), "WRONG-SIGNATURE");
        try { transfers.transfer(forged, "SAV2001", "CUR3001", new BigDecimal("999999")); }
        catch (SecurityException e) { log.severe("Forged token REJECTED: " + e.getMessage()); }
    }
}

// ─── token/Jwt.java (simplified bearer token with claims + roles + signature) ───
class Jwt {
    final String subject; final Set<String> roles; final String signature;
    Jwt(String subject, Set<String> roles, String signature) {
            this.subject = subject;
            this.roles = roles
            this.signature = signature;
    }
}

// ─── gateway/AuthGateway.java (authenticate + issue signed JWT; validate signature) ───
class AuthGateway {
    private final String signingKey;
    AuthGateway(String signingKey) { this.signingKey = signingKey; }
    Jwt login(String user, String password, Set<String> roles) {
        // Real code verifies credentials against the identity provider (OAuth2/OIDC).
        return new Jwt(user, roles, sign(user));
    }
    String sign(String subject) { return Integer.toHexString((subject + signingKey).hashCode()); }
    // Every service calls this — zero trust: validate signature on EVERY request.
    boolean isValid(Jwt token) { return sign(token.subject).equals(token.signature); }
}

// ─── authz/RbacAuthorizer.java (role → permission mapping) ───
class RbacAuthorizer {
    private final Map<String, Set<String>> rolePermissions = Map.of(
            "CUSTOMER", Set.of("VIEW_OWN", "TRANSFER"),
            "SUPPORT",  Set.of("VIEW_ANY"),              // NO transfer permission
            "TELLER",   Set.of("VIEW_ANY", "TRANSFER"));
    boolean hasPermission(Set<String> roles, String permission) {
        return roles.stream().anyMatch(r ->
                rolePermissions.getOrDefault(r, Set.of()).contains(permission));
    }
}

// ─── service/AccountService.java (independently authorizes — zero trust) ───
class AccountService {
    private static final Logger log = Logger.getLogger("Security");
    private final RbacAuthorizer authorizer;
    AccountService(RbacAuthorizer authorizer) { this.authorizer = authorizer; }
    void viewAccount(Jwt token, String accountId) {
        if (!authorizer.hasPermission(token.roles, "VIEW_ANY")
                && !authorizer.hasPermission(token.roles, "VIEW_OWN"))
            throw new SecurityException("no view permission");
        log.info(() -> token.subject + " viewed account " + accountId);
    }
}

// ─── service/TransferService.java (validates token + checks TRANSFER permission) ───
class TransferService {
    private static final Logger log = Logger.getLogger("Security");
    private final RbacAuthorizer authorizer;
    private final AuthGateway validator = new AuthGateway("nbin-signing-key-from-vault");
    TransferService(RbacAuthorizer authorizer) { this.authorizer = authorizer; }
    void transfer(Jwt token, String from, String to, BigDecimal amount) {
        if (!validator.isValid(token)) throw new SecurityException("invalid token signature");
        if (!authorizer.hasPermission(token.roles, "TRANSFER"))
            throw new SecurityException("role lacks TRANSFER permission");
        log.info(() -> "TRANSFER " + amount + " " + from + " → " + to
                + " authorized for " + token.subject);
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
